// Merge overlapping intervals - O(n log n)
function merge(intervals) {
  if (intervals.length <= 1) return intervals;

  // sort by start time
  intervals.sort((a, b) => a[0] - b[0]);

  const result = [intervals[0]];

  for (let i = 1; i < intervals.length; i++) {
    const last = result[result.length - 1];
    const curr = intervals[i];

    if (curr[0] <= last[1]) {
      // overlap - extend the last interval's end if needed
      last[1] = Math.max(last[1], curr[1]);
    } else {
      // no overlap - start a new merged interval
      result.push(curr);
    }
  }

  return result;
}

// Insert interval into sorted non-overlapping list - O(n)
function insert(intervals, newInterval) {
  const result = [];
  let i = 0;
  const n = intervals.length;

  // phase 1: add all intervals ending before newInterval starts
  while (i < n && intervals[i][1] < newInterval[0]) {
    result.push(intervals[i++]);
  }

  // phase 2: merge all overlapping intervals into newInterval
  while (i < n && intervals[i][0] <= newInterval[1]) {
    newInterval[0] = Math.min(newInterval[0], intervals[i][0]);
    newInterval[1] = Math.max(newInterval[1], intervals[i][1]);
    i++;
  }
  result.push(newInterval);

  // phase 3: add all remaining intervals
  while (i < n) result.push(intervals[i++]);

  return result;
}
